//! C3 against real CPython: `tests/fixtures/c3_cases.json` is generated by
//! `tests/gen_c3_cases.py`, which builds each hierarchy with `type()` and
//! records `__mro__` or the exact `TypeError`. Nothing here is hand-written.

use crush_cosm::*;
use serde::Deserialize;

#[derive(Deserialize)]
struct Doc {
    python: String,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    classes: Vec<Class>,
}

#[derive(Deserialize)]
struct Class {
    name: String,
    parents: Vec<String>,
    mro: Option<Vec<String>>,
    error: Option<String>,
}

fn python_class(name: &str, parents: &[String]) -> KindDecl {
    KindDecl {
        name: name.into(),
        home_lang: "python".into(),
        span: Some(Span::new(1, 1)),
        storage: Storage::OpenDict,
        semantics: Semantics::Reference,
        parents: parents.iter().map(|p| KindRef::from(p.as_str())).collect(),
        resolution: Resolution::C3,
        receiver: Receiver::BoundSelf,
        construct: Construct::PyNewInit {
            new_fn: None,
            init_fn: None,
        },
        members: vec![],
        hooks: Hooks::default(),
        conforms: vec![],
        equality: Equality::Identity,
    }
}

fn load() -> Doc {
    serde_json::from_str(include_str!("fixtures/c3_cases.json")).expect("c3_cases.json")
}

fn module_for(case: &Case) -> CosmModule {
    let mut module = CosmModule::new();
    module.kinds.push(python_class("object", &[]));
    for class in &case.classes {
        module.kinds.push(python_class(&class.name, &class.parents));
    }
    module
}

#[test]
fn fixtures_come_from_cpython() {
    let doc = load();
    assert!(doc.python.starts_with("CPython 3."), "{}", doc.python);
    assert!(doc.cases.len() >= 14);
}

#[test]
fn c3_matches_cpython_mro_and_errors() {
    let mut checked_mros = 0;
    let mut checked_errors = 0;
    for case in load().cases {
        let module = module_for(&case);
        for class in &case.classes {
            let got = module.c3_mro(&class.name);
            match (&class.mro, &class.error) {
                (Some(mro), None) => {
                    let got: Vec<String> = got
                        .unwrap_or_else(|e| {
                            panic!("{}: {}: unexpected error {e}", case.name, class.name)
                        })
                        .iter()
                        .map(|k| k.to_string())
                        .collect();
                    assert_eq!(&got, mro, "{}: MRO of {}", case.name, class.name);
                    // c3 kinds: resolution_order is the C3 MRO.
                    assert_eq!(
                        module.resolution_order(&class.name).unwrap().len(),
                        mro.len()
                    );
                    checked_mros += 1;
                }
                (None, Some(error)) => {
                    let err = got.expect_err(&format!("{}: {} should fail", case.name, class.name));
                    assert_eq!(
                        &err.to_string(),
                        error,
                        "{}: error for {}",
                        case.name,
                        class.name
                    );
                    assert_eq!(err.kind().as_str(), class.name);
                    checked_errors += 1;
                }
                _ => panic!("malformed fixture"),
            }
        }
    }
    assert_eq!(checked_mros, 60);
    assert_eq!(checked_errors, 6);
}

#[test]
fn validate_reports_cpython_errors_once_with_span() {
    for case in load().cases {
        let module = module_for(&case);
        let diags = validate(&module);
        let failing: Vec<&Class> = case.classes.iter().filter(|c| c.error.is_some()).collect();
        assert_eq!(diags.len(), failing.len(), "{}: {diags:#?}", case.name);
        for (d, class) in diags.iter().zip(failing) {
            let error = class.error.as_deref().unwrap();
            let code = if error.starts_with("duplicate base class") {
                DiagnosticCode::DuplicateBase
            } else {
                DiagnosticCode::InconsistentMro
            };
            assert_eq!(d.code, code);
            assert_eq!(d.subject, class.name);
            assert_eq!(d.message, error);
            assert_eq!(d.span, Some(Span::new(1, 1)));
        }
    }
}
